parameters.body/body/messageBody:
{
    "$schema": "https://adaptivecards.io/schemas/adaptive-card.json",
    "type": "AdaptiveCard",
    "version": "1.5",
    "body": [
        {
            "type": "TextBlock",
            "size": "Large",
            "weight": "Bolder",
            "id": "Title",
            "text": "Initiate @{outputs('Next_Project_State')?['vsb_name']} voting for project @{outputs('Project')?['body/vsb_projectname']}",
            "horizontalAlignment": "Left",
            "isSubtle": false,
            "style": "heading"
        },
        {
            "type": "TextBlock",
            "text": "Please confirm when the @{outputs('Next_Project_State')?['vsb_name']} meeting for project @{outputs('Project')?['body/vsb_projectname']} took place in order to initiate voting.\n\nRequest Due Date: @{body('ChildFlow_Checklist_Items')?['strFormatedApprovalDueDate']}\n\nRequest comment: @{outputs('Project_State_Tracking')?['body/vsb_approvalcomment']}\n",
            "wrap": true
        },
        {
            "id": "outGateMeetingDate",
            "type": "Input.Date",
            "errorMessage": "Please enter date, when gate meeting took place.",
            "placeholder": "Gate Meeting Date",
            "isRequired": true
        },
      {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
    {
      "type": "TextBlock",
      "text": "Project details:",
      "weight": "Bolder",
      "size": "Large",
      "horizontalAlignment": "Left",
      "isSubtle": true
    },
    {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Name",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Value",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        }
      ]
    },
     @{join(variables('arrAdaptiveCardProjectDetails'),',')},
    {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
    {
      "type": "TextBlock",
      "text": "Check List:",
      "weight": "Bolder",
      "size": "Large",
      "spacing": "Medium",
      "isSubtle": true
    },
    {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "State",
              "weight": "Bolder",
              "wrap": true
            }
          ]
        },{
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Description",
              "weight": "Bolder",
              "wrap": true
            }
          ]
        }

      ]
    },
    @{body('ChildFlow_Checklist_Items')?['strUnformattedCheckListItems']}
    ],
    "actions": [
        {
            "type": "Action.Submit",
            "title": "Submit"
        }
    ],
    "verticalContentAlignment": "Center",
    "lang": "en",
    "speak": "Please confirm when the @{outputs('Next_Project_State')?['vsb_name']} meeting for project @{outputs('Project')?['body/vsb_projectname']} took place in order to initiate voting."
}

